# agent_suivi.py
# Agent "suivi de commande" d'Atelia : une boucle agentique ecrite a la main
# avec l'appel d'outils natif (Chat Completions), sur Ollama en local.
#
# Usage : python agent_suivi.py "Ou en est ma commande AT-1001 ?"

import json
import logging
import re
import sys

from openai import OpenAI

MODELE = "qwen3:4b"            # a changer pour essayer un autre modele
MAX_ITERATIONS = 5             # garde-fou : nombre maximal de tours de boucle

# Ollama expose une API compatible OpenAI ; la cle est ignoree en local.
client = OpenAI(base_url="http://localhost:11434/v1", api_key="ollama")

# Journal sur la sortie d'erreur : chaque appel d'outil est trace.
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
journal = logging.getLogger("agent")

# ---------------------------------------------------------------------------
# 1. Les outils : de simples fonctions Python, ici avec des donnees simulees.
# ---------------------------------------------------------------------------
COMMANDES = {
    "AT-1001": {"statut": "expediee", "livraison_prevue": "2026-11-23",
                "point_relais": "Tabac du Marche, Lyon 3e"},
    "AT-1002": {"statut": "en preparation", "livraison_prevue": "2026-11-25",
                "point_relais": None},
    "AT-1003": {"statut": "livree", "livraison_prevue": "2026-11-12",
                "point_relais": "Librairie Centrale, Nantes"},
}


def suivre_commande(numero: str) -> dict:
    """Renvoie le statut d'une commande, ou un message si elle est inconnue."""
    commande = COMMANDES.get(numero)
    if commande is None:
        return {"trouvee": False, "message": f"Aucune commande {numero}."}
    return {"trouvee": True, "numero": numero, **commande}


def politique_retour(membre_atelia_plus: bool) -> dict:
    """Renvoie le delai de retour : 30 jours, ou 100 jours pour Atelia+."""
    return {"delai_jours": 100 if membre_atelia_plus else 30,
            "conditions": "Article en bon etat, avec preuve d'achat."}


# ---------------------------------------------------------------------------
# 2. La description des outils pour le modele (JSON Schema).
#    Le modele ne voit QUE ceci : nom, description et parametres.
# ---------------------------------------------------------------------------
OUTILS = [
    {
        "type": "function",
        "function": {
            "name": "suivre_commande",
            "description": "Donne le statut et la date de livraison prevue d'une commande Atelia.",
            "parameters": {
                "type": "object",
                "properties": {
                    "numero": {"type": "string",
                               "description": "Numero de commande, format AT-1234"},
                },
                "required": ["numero"],
                "additionalProperties": False,
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "politique_retour",
            "description": "Donne le delai de retour selon que le client est membre Atelia+ ou non.",
            "parameters": {
                "type": "object",
                "properties": {
                    "membre_atelia_plus": {"type": "boolean",
                                           "description": "Vrai si le client est membre Atelia+"},
                },
                "required": ["membre_atelia_plus"],
                "additionalProperties": False,
            },
        },
    },
]

# Table de correspondance : nom d'outil -> fonction Python autorisee.
FONCTIONS = {"suivre_commande": suivre_commande, "politique_retour": politique_retour}


def executer_outil(nom: str, arguments_json: str) -> dict:
    """Valide puis execute un appel d'outil propose par le modele."""
    # Garde-fou : on n'execute que les outils declares.
    if nom not in FONCTIONS:
        return {"erreur": f"Outil inconnu : {nom}"}
    # Les arguments arrivent sous forme de texte JSON, parfois mal forme.
    try:
        arguments = json.loads(arguments_json or "{}")
    except json.JSONDecodeError:
        return {"erreur": "Arguments JSON invalides."}
    # Validation metier minimale avant d'executer quoi que ce soit.
    if nom == "suivre_commande":
        numero = str(arguments.get("numero", "")).strip().upper()
        if not re.fullmatch(r"AT-\d{4}", numero):
            return {"erreur": "Numero de commande invalide : format attendu AT-1234."}
        return suivre_commande(numero)
    if nom == "politique_retour":
        membre = arguments.get("membre_atelia_plus")
        if not isinstance(membre, bool):
            return {"erreur": "membre_atelia_plus doit valoir true ou false."}
        return politique_retour(membre)
    return {"erreur": "Cas non prevu."}


CONSIGNE = (
    "Tu es l'assistant du service client d'Atelia, enseigne de maison et de decoration. "
    "Utilise les outils pour toute question sur une commande ou sur les retours. "
    "N'invente jamais un statut de commande. Si une information manque, "
    "demande-la au client. Reponds en francais, en trois phrases au plus."
)


def agent(question: str) -> str:
    """La boucle agentique : le modele propose, le code execute, on recommence."""
    messages = [
        {"role": "system", "content": CONSIGNE},
        {"role": "user", "content": question},
    ]
    for tour in range(1, MAX_ITERATIONS + 1):
        reponse = client.chat.completions.create(
            model=MODELE, messages=messages, tools=OUTILS, temperature=0,
        )
        message = reponse.choices[0].message

        # Pas d'appel d'outil : le modele a donne sa reponse finale.
        if not message.tool_calls:
            return message.content or ""

        # On rajoute a l'historique la demande d'appel du modele...
        messages.append({
            "role": "assistant",
            "content": message.content or "",
            "tool_calls": [
                {"id": appel.id, "type": "function",
                 "function": {"name": appel.function.name,
                              "arguments": appel.function.arguments}}
                for appel in message.tool_calls
            ],
        })
        # ... puis le resultat de chaque outil, avec le role "tool".
        for appel in message.tool_calls:
            resultat = executer_outil(appel.function.name, appel.function.arguments)
            journal.info("tour %d : %s(%s) -> %s", tour, appel.function.name,
                         appel.function.arguments, resultat)
            messages.append({
                "role": "tool",
                "tool_call_id": appel.id,
                "content": json.dumps(resultat, ensure_ascii=False),
            })

    # Garde-fou atteint : on s'arrete proprement au lieu de boucler.
    journal.warning("Arret : %d iterations atteintes", MAX_ITERATIONS)
    return "Je n'ai pas pu traiter votre demande. Un conseiller va vous recontacter."


if __name__ == "__main__":
    question = " ".join(sys.argv[1:]) or "Ou en est ma commande AT-1001 ?"
    print(agent(question))

# serveur_mcp_atelia.py
# Petit serveur MCP qui expose les outils du service client d'Atelia.
# SDK Python officiel "mcp", version 2.x : la classe FastMCP de la v1
# s'appelle desormais MCPServer.
#
# Lancement (transport stdio, par defaut) : python serveur_mcp_atelia.py
# Lancement en HTTP "streamable" :          python serveur_mcp_atelia.py --http

import sys
from typing import Annotated, Any

from pydantic import Field

from mcp.server import MCPServer

# Le nom et les instructions sont transmis au client lors de la connexion.
mcp = MCPServer(
    "atelia-service-client",
    instructions=(
        "Outils du service client Atelia : suivi de commande et politique "
        "de retour. Donnees fictives de formation."
    ),
)

# Le type de retour dict[str, Any] permet au SDK de renvoyer aussi un
# resultat structure (structured_content) en plus du texte JSON.

# Donnees simulees : dans la realite, on interrogerait le systeme de commandes.
COMMANDES = {
    "AT-1001": {"statut": "expediee", "transporteur": "Relais Express",
                "livraison_prevue": "2026-11-23", "point_relais": "Tabac du Marche, Lyon 3e"},
    "AT-1002": {"statut": "en preparation", "transporteur": None,
                "livraison_prevue": "2026-11-25", "point_relais": None},
    "AT-1003": {"statut": "livree", "transporteur": "Relais Express",
                "livraison_prevue": "2026-11-12", "point_relais": "Librairie Centrale, Nantes"},
}


@mcp.tool()
def suivre_commande(
    numero: Annotated[str, Field(description="Numero de commande Atelia, par exemple AT-1001",
                                 pattern=r"^AT-\d{4}$")],
) -> dict[str, Any]:
    """Donne le statut et la date de livraison prevue d'une commande Atelia."""
    commande = COMMANDES.get(numero)
    if commande is None:
        # Une erreur metier lisible par le modele, plutot qu'une exception brute.
        return {"trouvee": False, "message": f"Aucune commande {numero}."}
    return {"trouvee": True, "numero": numero, **commande}


@mcp.tool()
def politique_retour(
    membre_atelia_plus: Annotated[bool, Field(description="Vrai si le client est membre du programme Atelia+")],
) -> dict[str, Any]:
    """Indique le delai de retour applicable selon que le client est membre Atelia+ ou non."""
    delai = 100 if membre_atelia_plus else 30
    return {
        "delai_jours": delai,
        "conditions": "Article en bon etat, avec preuve d'achat. Retour en magasin ou en point relais.",
    }


@mcp.resource("atelia://garantie")
def garantie() -> str:
    """Texte de reference sur la garantie des meubles."""
    return "Les meubles Atelia sont garantis 2 ans a compter de la livraison."


@mcp.prompt()
def reponse_client(question: str) -> str:
    """Modele de demande pour repondre poliment a un client."""
    return (
        "Tu es l'assistant du service client Atelia. Reponds en francais, "
        "en trois phrases au plus, a la question suivante : " + question
    )


if __name__ == "__main__":
    if "--http" in sys.argv:
        # Ecoute sur http://127.0.0.1:8000/mcp (chemin par defaut).
        mcp.run("streamable-http", host="127.0.0.1", port=8000)
    else:
        # stdio : le client lance ce script et dialogue par l'entree et la sortie standard.
        mcp.run()

