"""Mini-banc d'évaluation d'Atelia Conseil (parcours B, module B5).

Le script pose les questions de cas-tests.json à plusieurs configurations
(un modèle + un prompt système), puis note chaque réponse de deux façons :
  1. par des règles simples (mots attendus, mots interdits, longueur) ;
  2. par un LLM-juge qui compare la réponse à la réponse de référence.
Il affiche un tableau comparatif et enregistre tout dans un fichier JSON.

Utilisation :
  python banc_evaluation.py                     # interroge Ollama
  python banc_evaluation.py --a-sec             # test à sec, sans Ollama
  python banc_evaluation.py --sortie v2.json --reference v1.json
"""

import argparse
import hashlib
import json
import re
import sys
import time
import unicodedata
from datetime import datetime
from pathlib import Path
from types import SimpleNamespace

# --- Réglages : changez ici le modèle, ou basculez vers un fournisseur cloud ---
MODELE = "qwen3:4b"
MODELE_JUGE = MODELE  # idéalement un modèle différent, et plus fort
BASE_URL = "http://localhost:11434/v1"  # Ollama ; pour un cloud, son URL
CLE_API = "ollama"  # ignorée par Ollama ; pour un cloud, lisez une variable d'environnement
DESACTIVER_REFLEXION = True  # mettez False si le modèle n'a pas de mode réflexion
SEED = 42
SEUIL_REGLES = 0.75  # part minimale de cas réussis aux règles
SEUIL_JUGE = 3.5  # note moyenne minimale du juge (sur 5)

# Chaque configuration = un nom, un modèle et un fichier de prompt système.
CONFIGURATIONS = [
    {"nom": "A-prompt-court", "modele": MODELE, "prompt": "prompt-a.txt"},
    {"nom": "B-prompt-detaille", "modele": MODELE, "prompt": "prompt-b.txt"},
    # Étape optionnelle du TP : le modèle créé avec le Modelfile.
    # Son prompt système est déjà intégré, d'où "prompt": None.
    # {"nom": "C-modelfile", "modele": "atelia-conseil", "prompt": None},
]

CONSIGNE_JUGE = """Tu es un évaluateur strict et impartial pour le service client d'Atelia.
On te donne la question d'un client, une réponse de référence et la réponse à évaluer.
Note la réponse à évaluer de 1 à 5 :
5 = exacte, complète et courtoise ; 4 = exacte avec un défaut mineur ;
3 = partiellement exacte ou incomplète ; 2 = contient une erreur importante ;
1 = fausse, inventée ou hors sujet.
Critères : exactitude par rapport à la référence, aucune information inventée
(prix, délais, conditions), ton courtois. Ne favorise pas les réponses longues.
Réponds uniquement avec un objet JSON de la forme :
{"note": <entier de 1 à 5>, "justification": "<une phrase>"}"""


def normaliser(texte):
    """Minuscules, sans accents ni espaces multiples, pour comparer des mots."""
    texte = unicodedata.normalize("NFKD", texte.lower())
    texte = "".join(c for c in texte if not unicodedata.combining(c))
    texte = texte.replace(chr(0x2019), "'")  # apostrophe typographique -> droite
    return re.sub(r"\s+", " ", texte).strip()


def nettoyer_reponse(texte):
    """Retire un éventuel raisonnement entre balises <think> laissé dans la réponse."""
    return re.sub(r"<think>.*?</think>", "", texte or "", flags=re.DOTALL).strip()


def empreinte(texte):
    """Empreinte courte d'un prompt : permet de savoir quelle version a été testée."""
    if texte is None:
        return None
    return hashlib.sha256(texte.encode("utf-8")).hexdigest()[:12]


class ClientSimule:
    """Faux client pour le test à sec : imite client.chat.completions.create()."""

    def __init__(self, cas):
        self.reponses = {c["question"]: c["attendu"] for c in cas}
        self.chat = SimpleNamespace(completions=SimpleNamespace(create=self._creer))
        self.models = SimpleNamespace(list=lambda: [])

    def _creer(self, model, messages, **options):
        systeme = messages[0]["content"] if messages[0]["role"] == "system" else ""
        question = messages[-1]["content"]
        if systeme.startswith("Tu es un évaluateur"):
            texte = '{"note": 4, "justification": "Réponse simulée par le test à sec."}'
        elif "100 jours" in systeme or model == "atelia-conseil":
            texte = self.reponses.get(question, "Je ne sais pas.")
        else:
            texte = "Bonjour, merci pour votre message. Contactez notre service client."
        usage = SimpleNamespace(prompt_tokens=len(question) // 4, completion_tokens=len(texte) // 4)
        message = SimpleNamespace(content=texte)
        return SimpleNamespace(choices=[SimpleNamespace(message=message)], usage=usage)


def creer_client(a_sec, cas):
    if a_sec:
        return ClientSimule(cas)
    from openai import OpenAI  # importé ici pour que le test à sec marche sans le SDK

    return OpenAI(base_url=BASE_URL, api_key=CLE_API)


def appeler(client, modele, messages, json_attendu=False):
    """Envoie une requête ; renvoie le texte, la latence (s) et les tokens consommés."""
    options = {"model": modele, "messages": messages, "temperature": 0, "seed": SEED}
    if DESACTIVER_REFLEXION:
        options["reasoning_effort"] = "none"
    if json_attendu:
        options["response_format"] = {"type": "json_object"}
    debut = time.perf_counter()
    reponse = client.chat.completions.create(**options)
    latence = time.perf_counter() - debut
    usage = getattr(reponse, "usage", None)
    tokens = {
        "entree": getattr(usage, "prompt_tokens", 0) or 0,
        "sortie": getattr(usage, "completion_tokens", 0) or 0,
    }
    return nettoyer_reponse(reponse.choices[0].message.content), latence, tokens


def noter_regles(reponse, cas):
    """Règles déterministes : chaque groupe de mots attendus, aucun mot interdit, longueur."""
    texte = normaliser(reponse)
    echecs = []
    for groupe in cas["doit_contenir"]:
        if not any(normaliser(mot) in texte for mot in groupe):
            echecs.append("manque : " + " / ".join(groupe))
    for mot in cas["ne_doit_pas_contenir"]:
        if normaliser(mot) in texte:
            echecs.append("interdit : " + mot)
    if len(reponse) > cas["longueur_max"]:
        echecs.append("trop long : %d caractères" % len(reponse))
    return {"ok": not echecs, "echecs": echecs}


def lire_note(texte):
    """Extrait la note du JSON du juge ; tolère un JSON mal formé."""
    try:
        donnees = json.loads(texte)
        note = int(donnees["note"])
        justification = str(donnees.get("justification", ""))
    except (ValueError, KeyError, TypeError):
        trouve = re.search(r"note\D{0,5}([1-5])", texte)
        if not trouve:
            return None, "Réponse du juge illisible : " + texte[:80]
        note, justification = int(trouve.group(1)), "(JSON mal formé)"
    return min(max(note, 1), 5), justification


def noter_juge(client, cas, reponse):
    message = (
        "Question du client :\n" + cas["question"]
        + "\n\nRéponse de référence :\n" + cas["attendu"]
        + "\n\nRéponse à évaluer :\n" + reponse
    )
    messages = [
        {"role": "system", "content": CONSIGNE_JUGE},
        {"role": "user", "content": message},
    ]
    texte, _, _ = appeler(client, MODELE_JUGE, messages, json_attendu=True)
    note, justification = lire_note(texte)
    return {"note": note, "justification": justification}


def evaluer_configuration(client, config, cas_liste, dossier):
    prompt = None
    if config["prompt"]:
        prompt = (dossier / config["prompt"]).read_text(encoding="utf-8")
    resultats = []
    for cas in cas_liste:
        messages = [{"role": "user", "content": cas["question"]}]
        if prompt:
            messages.insert(0, {"role": "system", "content": prompt})
        try:
            reponse, latence, tokens = appeler(client, config["modele"], messages)
            regles = noter_regles(reponse, cas)
            juge = noter_juge(client, cas, reponse)
        except Exception as erreur:  # une panne ne doit pas arrêter tout le banc
            reponse, latence, tokens = "", 0.0, {"entree": 0, "sortie": 0}
            regles = {"ok": False, "echecs": ["erreur : %s" % erreur]}
            juge = {"note": None, "justification": "non évalué"}
        print("  %-20s règles %-4s juge %s" % (cas["id"], "OK" if regles["ok"] else "KO", juge["note"]))
        resultats.append({
            "id": cas["id"], "reponse": reponse, "latence_s": round(latence, 2),
            "tokens": tokens, "regles": regles, "juge": juge,
        })
    return {
        "nom": config["nom"], "modele": config["modele"], "prompt": config["prompt"],
        "empreinte_prompt": empreinte(prompt), "resultats": resultats,
    }


def synthese(evaluation):
    res = evaluation["resultats"]
    notes = [r["juge"]["note"] for r in res if r["juge"]["note"] is not None]
    return {
        "reussite_regles": sum(r["regles"]["ok"] for r in res) / len(res),
        "note_juge": sum(notes) / len(notes) if notes else 0.0,
        "latence_moyenne_s": sum(r["latence_s"] for r in res) / len(res),
        "tokens_sortie": sum(r["tokens"]["sortie"] for r in res),
    }


def comparer_reference(evaluations, chemin_reference):
    """Signale les cas réussis dans l'ancien rapport et échoués maintenant."""
    ancien = json.loads(Path(chemin_reference).read_text(encoding="utf-8"))
    anciens_ok = {
        (e["nom"], r["id"]) for e in ancien["evaluations"] for r in e["resultats"] if r["regles"]["ok"]
    }
    regressions = []
    for e in evaluations:
        for r in e["resultats"]:
            if (e["nom"], r["id"]) in anciens_ok and not r["regles"]["ok"]:
                regressions.append("%s / %s : %s" % (e["nom"], r["id"], "; ".join(r["regles"]["echecs"])))
    return regressions


def main():
    parser = argparse.ArgumentParser(description="Mini-banc d'évaluation Atelia Conseil")
    parser.add_argument("--a-sec", action="store_true", help="réponses simulées, sans Ollama")
    parser.add_argument("--cas", default="cas-tests.json", help="fichier du jeu d'évaluation")
    parser.add_argument("--sortie", default=None, help="fichier JSON des résultats")
    parser.add_argument("--reference", default=None, help="ancien fichier de résultats à comparer")
    args = parser.parse_args()

    dossier = Path(__file__).resolve().parent
    jeu = json.loads((dossier / args.cas).read_text(encoding="utf-8"))
    cas_liste = jeu["cas"]
    client = creer_client(args.a_sec, cas_liste)

    try:
        client.models.list()  # vérifie que le serveur répond avant de lancer le banc
    except Exception as erreur:
        sys.exit("Serveur injoignable (%s). Ollama est-il lancé ?" % erreur)

    evaluations = []
    for config in CONFIGURATIONS:
        print("\nConfiguration %s (modèle %s)" % (config["nom"], config["modele"]))
        evaluations.append(evaluer_configuration(client, config, cas_liste, dossier))

    print("\n%-20s %8s %8s %10s %8s" % ("Configuration", "Règles", "Juge/5", "Latence", "Tokens"))
    alertes = []
    for e in evaluations:
        s = e["synthese"] = synthese(e)
        print("%-20s %7.0f%% %8.2f %9.2fs %8d" % (
            e["nom"], 100 * s["reussite_regles"], s["note_juge"], s["latence_moyenne_s"], s["tokens_sortie"]))
        if s["reussite_regles"] < SEUIL_REGLES or s["note_juge"] < SEUIL_JUGE:
            alertes.append("%s sous les seuils" % e["nom"])

    if args.reference:
        regressions = comparer_reference(evaluations, args.reference)
        print("\nRégressions par rapport à %s : %d" % (args.reference, len(regressions)))
        for ligne in regressions:
            print("  - " + ligne)
        alertes += regressions

    horodatage = datetime.now().strftime("%Y%m%d-%H%M%S")
    sortie = Path(args.sortie or "resultats-%s.json" % horodatage)
    rapport = {
        "date": datetime.now().isoformat(timespec="seconds"),
        "jeu": {"fichier": args.cas, "version": jeu.get("version")},
        "modele_juge": MODELE_JUGE, "a_sec": args.a_sec, "evaluations": evaluations,
    }
    sortie.write_text(json.dumps(rapport, ensure_ascii=False, indent=1), encoding="utf-8")
    print("\nRésultats détaillés : %s" % sortie)
    for alerte in alertes:
        print("ALERTE : " + alerte)
    sys.exit(1 if alertes else 0)  # code non nul : utile en intégration continue


if __name__ == "__main__":
    main()
